content.content:
1	/**
2	 * Screen 04 milestone M4 (round 8, qa/match/04/NOTES.md) — sub-switches of `?match04=1`, each `&m04…=1`, default off:
3	 *  m04ring  — the gold washer opening and the gold-ring tunnel as REAL modeled geometry (lathe profiles sized from the
4	 *             approved picture's mouth ring r 3.58 → 4.11 and the painted stacked ring bands), shaded as polished gold
5	 *             (warm glow down the tunnel, pink / violet / cyan water reflections on the lower walls, glints, a row of
6	 *             amber bulbs on the opening and on every ring lip). In the approved view these surfaces show the approved
7	 *             pixels (camera projection, unchanged); they fade to their own crisp 3D gold as the camera leaves that view.
8	 *  m04foam  — puffy 3D foam banks along both water edges (the painted white-lilac foam clusters), hidden in the approved
9	 *             view (the painting carries them there), shown once the camera has left it.
10	 *  m04bub   — iridescent soap bubbles floating in the tunnel air (camera-facing bubble discs), same visibility rule.
11	 *  m04arrow — the five glowing blue chevron arrows drawn crisp on the water (distance-field shape at the painted
12	 *             spacing) instead of the magnified painted arrow tile.
13	 *  m04wave  — the painted swirl water without the obvious repeat (two offset samples of the swirl tile blended by a
14	 *             slow world-anchored noise) and flowing down the slide.
15	 *  m04foam3 — (round 9, with m04foam + m04river) LOW soft foam hugging the river banks (heaps a third as tall, smaller
16	 *             puffs, wider gaps where the pink water shows), lavender / pink shaded like the painted foam.
17	 *  m04pink  — (round 9, with m04river) the broad pink / magenta swirl bands on both sides of the narrow cyan arrow lane.
18	 *  m04arr5  — (round 9, with m04river) the five glowing chevrons as painted: fat flat white-cyan bars nested one after
19	 *             the other ahead of Benny (about five in view at a time, the farther ones fading into the glow).
20	 *  m04mouth — (round 9, needs m04ring) the approved GOLD WASHER OPENING: the painted mouth ring (thick polished band,
21	 *             thin bright lips, dark groove) unwrapped from the approved pixels and straightened (tools/match04/mouth04.py
22	 *             -> tile_mouth.png) on a modeled mouth ring flush with the painted ring plane, mapped through the projector so
23	 *             the approach continues the approved view; its row of glowing bulbs (the painted hot spots on both lips,
24	 *             mouth04.json) drawn as crisp glowing bulbs at any distance.
25	 * Without `?match04=1` nothing here runs; without the sub-switches nothing here is built.
26	 */
27	import * as THREE from 'three';
28	import { PROJ05_INVERSE } from '../vfx/waterRibbon';
29	
30	const QS = new URLSearchParams(location.search);
31	const on = (k: string) => QS.get(k) === '1';
32	export const M04 = {
33	  ring: on('m04ring'),
34	  foam: on('m04foam'),
35	  bub: on('m04bub'),
36	  arrow: on('m04arrow'),
37	  wave: on('m04wave'),
38	  river: on('m04river'),
39	  gold: on('m04gold'),
40	  mouth: on('m04mouth'),
41	  room: on('m04room'),
42	  foam3: on('m04foam3'),
43	  pink: on('m04pink'),
44	  arr5: on('m04arr5'),
45	  arr3d: on('m04arr3d'),
46	  lay: on('m04lay'),
47	  num: (k: string, d: number) => (QS.has(k) ? Number(QS.get(k)) : d),
48	};
49	
50	export interface M04Ctx {
51	  group: THREE.Group;
52	  shared: Record<string, THREE.IUniform>;
53	  proj: THREE.PerspectiveCamera;
54	  /** tube axis in group-local coordinates (x lateral, y up from the slide, z = -down the slide) */
55	  cx: number; cy: number; z0: number; len: number; r: number; outerR: number;
56	  hideOld: (names: string[]) => void;
57	}
58	
59	const VERT = /* glsl */ `
60	uniform mat4 uProjVP;
61	attribute vec2 aK;
62	#ifdef RFEW
63	attribute vec2 aF;          // r18 m04rfew: x = ring coordinate along the tunnel in painted-period units, y = ring scale
64	varying vec2 vF;
65	#endif
66	varying vec4 vProj;
67	varying vec3 vW;
68	varying vec3 vN;
69	varying vec2 vK;
70	void main() {
71	  vec4 wp = modelMatrix * vec4(position, 1.0);
72	  vProj = uProjVP * wp;
73	  vW = wp.xyz;
74	  vK = aK;
75	#ifdef RFEW
76	  vF = aF;
77	#endif
78	  vN = normalize(mat3(modelMatrix) * normal);
79	  gl_Position = projectionMatrix * viewMatrix * wp;
80	}`;
81	
82	// polished gold, art-directed in DISPLAY colours measured on the approved picture (then pjInverse like the plate):
83	// groove (110,35,5) / shadow band (168,70,18) / mid (205,97,28) / lit (245,143,38) / hot lip (255,204,77) / glint.
84	// Each ring = a broad polished band that brightens toward its lip, a bright rounded lip with hot spots, a thin dark groove;
85	// the far rings warm toward the glowing vanishing point; violet / pink water reflections on the lower walls.
86	const GOLD_FRAG = /* glsl */ `
87	uniform sampler2D uPlate;
88	uniform vec4 uPjPost;
89	uniform vec2 uPjRes;
90	uniform float uAway;
91	uniform vec3 uAxO;
92	uniform vec3 uAxD;
93	uniform vec3 uAxU;
94	uniform vec3 uAxR;
95	uniform float uNB;
96	uniform float uP;
97	uniform float uLipBulb;
98	uniform float uBulbR;
99	uniform float uLen;
100	uniform vec4 uTone;        // band base, lip base, opening base, streak strength
101	uniform sampler2D uRingTile; // tile_ring.png: the painted ring colour at every angle (rows 56..176 = band near edge .. lip)
102	uniform float uPaint;      // how much of the painted ring colour drives the bands (m04paint)
103	uniform float uBulge;      // r13 m04bulge: each band shaded as a ROUNDED tube (bright middle, darker edges) like the painted rings
104	uniform float uCopper;     // r13 m04copper: rich polished COPPER-gold ramp (dark maroon grooves -> copper -> warm-gold highlights)
105	uniform float uGoldY;      // m04gold: polished YELLOW-gold ramp (bright yellow-white highlights), fewer magenta tints
106	uniform float uMouthT;     // m04mouth: the painted mouth ring texture on the opening (tile_mouth.png)
107	uniform sampler2D uMouthTex;
108	uniform vec3 uMouthRho;    // tile rows: rho at the top row, rho at the bottom row (fitted mouth plane z0); z: rho offset
109	                           // (the painted band lies 0.1 u inside the fitted outer radius: lips onto the modeled lips)
110	uniform vec3 uProjPos;
111	uniform float uRPaint;     // r15 m04rpaint: mix of the user's PAINTED inner ring (tile_ring_paint.png) on every inner ring band
112	uniform sampler2D uRTex;   // cols psi -pi..pi (0 = top, + = right), rows s 0 (painted groove) .. 1 (next groove), deeper
113	uniform vec4 uRLip;        // x: painted lip-line s, y: modeled u that carries the painted lip line, z: modeled shading amount,
114	                           // w: modeled u where the painted groove begins (held dark to the period end)
115	uniform float uRJit;       // per-ring angle offset (rad, +-): the painted highlights do not line up ring after ring
116	uniform vec2 uRWarm;       // r16 m04rwarm: x = amount, y = where the grade starts (fraction of the camera -> end-glow distance)
117	uniform vec4 uRDots;       // r16 m04rpdots: x = amount, y = dot cells per ring, z = fraction of cells lit, w = core radius (u)
118	uniform float uRVar;       // r17 m04rpvar: number of painted rings stacked in the atlas (0 = the single painted ring 1)
119	uniform vec4 uRPol;        // r18 m04rpol: x amount, y luma pivot, z contrast gain above it, w below it
120	uniform vec2 uRPol2;       // r18 m04rpol: x sharp sheen (reflection of the bright end), y grazing-angle brightening
121	uniform vec4 uRCr;         // r18 m04rpcr: x amount, y bright lip line half width, z dark lip-edge line half width, w band-start corner (u)
122	#ifdef RFEW
123	uniform float uRFewG;      // r18 m04rfew: height of the telescope's shrink centre (group units, from the axis; < 0 = below)
124	uniform vec2 uRFewW;       // r18 m04rfew: x = ring scale where the deep rings reach warm yellow-white, y = amount (m04rfw, m04rfk)
125	uniform vec3 uRFewE;       // r18 m04rfew: world position of the telescope's end (the light)
126	uniform vec3 uRFewL;       // r18 m04rfew: light strength, core and glow angular radius (rad) (m04rfl, m04rfc, m04rfo)
127	varying vec2 vF;
128	#endif
129	varying vec4 vProj;
130	varying vec3 vW;
131	varying vec3 vN;
132	varying vec2 vK;            // x: part (0 band, 1 lip, 2 groove, 3 opening face, 4 end glow), y: ring index (-1 = opening)
133	${PROJ05_INVERSE}
134	float h21(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
135	vec3 goldRamp(float x) {
136	  x = clamp(x, 0.0, 1.0) * 5.0;
137	  vec3 c0 = vec3(0.43, 0.14, 0.02), c1 = vec3(0.66, 0.27, 0.07), c2 = vec3(0.80, 0.38, 0.11);
138	  vec3 c3 = vec3(0.96, 0.56, 0.15), c4 = vec3(1.0, 0.80, 0.30), c5 = vec3(1.0, 0.96, 0.80);
139	  if (x < 1.0) return mix(c0, c1, x);
140	  if (x < 2.0) return mix(c1, c2, x - 1.0);
141	  if (x < 3.0) return mix(c2, c3, x - 2.0);
142	  if (x < 4.0) return mix(c3, c4, x - 3.0);
143	  return mix(c4, c5, x - 4.0);
144	}
145	vec3 goldRampC(float x) {
146	  x = clamp(x, 0.0, 1.0) * 5.0;
147	  vec3 c0 = vec3(0.17, 0.04, 0.03), c1 = vec3(0.42, 0.13, 0.06), c2 = vec3(0.66, 0.29, 0.12);
148	  vec3 c3 = vec3(0.86, 0.50, 0.22), c4 = vec3(0.98, 0.76, 0.44), c5 = vec3(1.0, 0.95, 0.86);
149	  if (x < 1.0) return mix(c0, c1, x);
150	  if (x < 2.0) return mix(c1, c2, x - 1.0);
151	  if (x < 3.0) return mix(c2, c3, x - 2.0);
152	  if (x < 4.0) return mix(c3, c4, x - 3.0);
153	  return mix(c4, c5, x - 4.0);
154	}
155	vec3 goldRampY(float x) {
156	  x = clamp(x, 0.0, 1.0) * 5.0;
157	  vec3 c0 = vec3(0.52, 0.22, 0.03), c1 = vec3(0.76, 0.40, 0.07), c2 = vec3(0.89, 0.55, 0.12);
158	  vec3 c3 = vec3(0.98, 0.72, 0.20), c4 = vec3(1.0, 0.87, 0.42), c5 = vec3(1.0, 0.98, 0.86);
159	  if (x < 1.0) return mix(c0, c1, x);
160	  if (x < 2.0) return mix(c1, c2, x - 1.0);
161	  if (x < 3.0) return mix(c2, c3, x - 2.0);
162	  if (x < 4.0) return mix(c3, c4, x - 3.0);
163	  return mix(c4, c5, x - 4.0);
164	}
165	// a few long highlight streaks around the ring (painted smears), different on every ring
166	float streaks(float ang, float ring) {
167	  float s = 0.0;
168	  for (int i = 0; i < 4; i++) {
169	    float fi = float(i);
170	    float c = (h21(vec2(ring, fi * 3.1)) * 2.0 - 1.0) * 2.6;
171	    float w = 0.12 + 0.30 * h21(vec2(ring, fi * 5.7));
172	    float d = ang - c; d = mod(d + 3.14159, 6.28318) - 3.14159;
173	    s += (0.45 + 0.55 * h21(vec2(ring, fi * 9.3))) * exp(-d * d / (w * w));
174	  }
175	  return s;
176	}
177	void main() {
178	  vec3 V = normalize(cameraPosition - vW);
179	  vec3 n = normalize(vN);
180	  if (dot(n, V) < 0.0) n = -n;
181	  vec3 q = vW - uAxO;
182	  float al = dot(q, uAxD);
183	  vec3 qr = q - uAxD * al;
184	  float rr = length(qr);
185	  float ang = atan(dot(qr, uAxR), dot(qr, uAxU));         // 0 = tunnel top, < 0 = left
186	#ifdef RFEW
187	  if (vK.y > -0.5) {
188	    // r18 m04rfew: telescoping rings — every ring is a copy of the template ring scaled by vF.y about a centre on the
189	    // water line; angle and radius are taken around the ring's OWN centre, in template units, and the position along
190	    // the ring comes from the ring coordinate (painted-period units), so texture, lip, groove and dots shrink with it
191	    float sF = max(vF.y, 1e-3);
192	    qr -= uAxU * (1.0 - sF) * uRFewG;
193	    rr = length(qr) / sF;
194	    ang = atan(dot(qr, uAxR), dot(qr, uAxU));
195	    al = vF.x;
196	  }
197	#endif
198	  vec3 R = reflect(-V, n);
199	  float part = vK.x;
200	  float dc = distance(cameraPosition, vW);
201	  float facing = clamp(dot(n, V), 0.0, 1.0);
202	  vec3 col;
203	  if (part > 3.5) {
204	    // the far glow (painted vanishing point): small warm-white core, orange-gold outside with faint far rings
205	    // soft warm-white core, yellow-orange glow, orange toward the rim (matches the far bands), no hard target rings
206	    float rad = clamp(rr / 3.6, 0.0, 1.0);
207	    col = mix(vec3(1.0, 0.95, 0.78), vec3(1.0, 0.72, 0.24), smoothstep(0.04, 0.30, rad));
208	    col = mix(col, uGoldY > 0.5 ? vec3(0.98, 0.70, 0.22) : vec3(0.93, 0.52, 0.15), smoothstep(0.30, 0.95, rad));
209	    col *= 1.0 - 0.10 * smoothstep(0.25, 0.0, abs(fract(log(max(rad, 0.01)) / log(0.72)) - 0.5)) * smoothstep(0.35, 0.7, rad);
210	  } else {
211	    bool mouth = vK.y < -0.5;
212	    float ring = floor(vK.y + 0.5);             // integer ring index (the interpolated varying is not exact)
213	    float v, tb = 0.0;
214	    // gloss that moves with the view: the polished metal reflects the bright far end of the tunnel
215	    float gl = pow(max(dot(R, uAxD), 0.0), 6.0);
216	    if (mouth) {
217	      // the washer opening: thick bright polished gold, a long vertical highlight, glowing rounded lips
218	      float st = streaks(ang, 77.0);
219	      v = uTone.z + 0.08 * cos(ang) + 0.20 * st + 0.08 * gl;
220	      if (part > 0.5 && part < 1.5) v = uTone.z + 0.14 + 0.16 * facing + 0.10 * st;
221	      if (part > 1.5 && part < 2.5) v = 0.18;
222	    } else {
223	      float u = fract(al / uP) * uP;                       // world units inside this ring period (0 = groove step)
224	      float t = clamp((u - 0.06) / (uP - 0.6), 0.0, 1.0);  // band: 0 at its near edge .. 1 at its lip
225	      float far = smoothstep(10.0, 38.0, dc);
226	      float st = streaks(ang, ring);
227	      tb = t;
228	      float bump = smoothstep(0.0, 0.45, t) * (1.0 - 0.5 * smoothstep(0.7, 1.0, t));
229	      v = uTone.x + 0.20 * pow(t, 1.5) + 0.03 * cos(ang) + 0.04 * far + uTone.w * st * bump + 0.05 * gl;
230	      v += uBulge * (sin(3.14159 * t) - 0.35);
231	      if (part > 0.5 && part < 1.5) v = uTone.y + 0.12 * facing + 0.04 * far + 0.15 * st;
232	      if (part > 1.5 && part < 2.5) v = 0.03 + 0.05 * far;
233	    }
234	    col = uCopper > 0.5 ? goldRampC(v * uCopper) : (uGoldY > 0.5 ? goldRampY(v) : goldRamp(v));
235	    if (!mouth && part < 1.5) {
236	      // the painted ring colour at this angle (pinks, violets, yellow streaks of the approved rings), with the crisp
237	      // structure's brightness: painted palette + modeled lip / groove / highlight shapes
238	      float row = part > 0.5 ? 0.92 : mix(0.30, 0.90, tb);
239	      vec3 pc = texture2D(uRingTile, vec2(0.5 - ang / 6.2831853, row)).rgb;
240	      // painted variation only (this angle's colour minus the painted row average): the pink / violet / yellow streaks
241	      // ride on the measured gold ramp, so dark gold stays deep orange (scaling a yellow down would turn it olive)
242	      vec3 rm = mix(vec3(0.73, 0.33, 0.11), vec3(0.83, 0.42, 0.18), smoothstep(0.30, 0.45, row));
243	      rm = mix(rm, vec3(0.87, 0.49, 0.19), smoothstep(0.45, 0.60, row));
244	      rm = mix(rm, vec3(0.89, 0.59, 0.26), smoothstep(0.60, 0.75, row));
245	      rm = mix(rm, vec3(0.92, 0.76, 0.38), smoothstep(0.75, 0.92, row));
246	      col = clamp(col + uPaint * (pc - rm), 0.0, 1.0);
247	    }
248	    // violet (left) / pink (right) reflections of the swirl water on the lower walls, painterly variation above
249	    float low = smoothstep(1.25, 2.15, abs(ang));
250	    vec3 wc = ang < 0.0 ? vec3(0.62, 0.42, 0.86) : vec3(0.95, 0.42, 0.70);
251	    float ry = mouth ? 99.0 : ring, fa = ang * 2.2 + ry * 1.7;
252	    float hv = mix(h21(vec2(floor(fa), ry)), h21(vec2(floor(fa) + 1.0, ry)), smoothstep(0.0, 1.0, fract(fa)));
253	    float pk = (0.42 * low + 0.22 * smoothstep(0.78, 0.98, hv) * (1.0 - low)) * (part > 0.5 && part < 1.5 ? 0.35 : 1.0);
254	    vec3 wc2 = mix(wc, vec3(0.88, 0.42, 0.78), 1.0 - low);   // dusky violet-pink tint on the upper walls
255	    col = mix(col, wc2 * (0.55 + 0.6 * v), pk * (mouth ? 0.6 : 1.0) * (1.0 - 0.55 * uGoldY));
256	    // a few cool blue-violet glints on the bands (painted reflections of the cyan water)
257	    if (!mouth && part < 0.5) {
258	      float cb = streaks(ang + 1.3, ring + 31.0);
259	      col = mix(col, vec3(0.62, 0.66, 1.0), 0.55 * smoothstep(0.7, 1.0, cb) * step(0.55, h21(vec2(ring, 4.4))) * smoothstep(0.1, 0.5, tb));
260	    }
261	    // hot spots / amber bulbs: a row on the opening's face, smaller glints on every ring lip
262	    bool onFace = part > 2.5 && part < 3.5;
263	    bool onLip = uLipBulb > 0.5 && part > 0.5 && part < 1.5 && !mouth;
264	    if (onFace || onLip) {
265	      float nb = onFace ? uNB : floor(uNB * 0.6);
266	      float cell = fract(ang / 6.2831853 * nb + 0.5 * mod(max(ring, 0.0), 2.0)) - 0.5;
267	      float arc = cell * 6.2831853 * rr / nb;               // world units along the ring
268	      float rad = onFace ? abs(rr - uBulbR) : 0.0;
269	      float d = length(vec2(arc, rad));
270	      float bs = onFace ? 0.075 : 0.05;
271	      float on = onFace ? 1.0 : step(0.35, h21(vec2(floor(ang / 6.2831853 * nb + 0.5), ring)));
272	      on *= 1.0 - smoothstep(0.4, 1.0, fwidth(arc) / bs);
273	      col += vec3(1.0, 0.55, 0.12) * 0.55 * smoothstep(bs * 3.5, 0.0, d) * on;
274	      col = mix(col, vec3(1.0, 0.95, 0.75), smoothstep(bs, bs * 0.35, d) * on);
275	    }
276	    // star glints scattered on the polished gold (painted white sparkles), sparse
277	    vec2 gc = vec2(ang / 6.2831853 * 30.0, al * 1.1);
278	    vec2 gi = floor(gc), gf = fract(gc) - 0.5;
279	    float gh = h21(gi + ring * 7.0);
280	    float gfw = max(fwidth(gc.x), fwidth(gc.y));
281	    if (gh > 0.93 && gfw < 0.35) {
282	      vec2 o = (vec2(h21(gi + 1.3), h21(gi + 2.7)) - 0.5) * 0.6;
283	      vec2 p = (gf - o) * vec2(1.0, 0.7);
284	      float g = smoothstep(0.08, 0.0, length(p)) + 0.4 * smoothstep(0.02, 0.0, abs(p.x)) * smoothstep(0.28, 0.0, abs(p.y)) + 0.4 * smoothstep(0.02, 0.0, abs(p.y)) * smoothstep(0.28, 0.0, abs(p.x));
285	      col += vec3(1.0, 0.92, 0.70) * g * 0.6 * (1.0 - smoothstep(0.15, 0.35, gfw));
286	    }
287	    if (mouth && uMouthT > 0.5) {
288	      // m04mouth: the painted washer opening. The fragment is carried along the projector ray onto the fitted mouth plane
289	      // (homothety about the projector), so the approach continues the approved view; (psi, rho) there index the
290	      // straightened painted ring. Deeper parts of the inner lip land on the painted groove / inner band rows.
291	      float dP = dot(vW - uProjPos, uAxD), d0 = dot(uAxO - uProjPos, uAxD);
292	      vec3 Q = uProjPos + (vW - uProjPos) * (d0 / max(dP, 0.5));
293	      vec3 qq = Q - uAxO; qq -= uAxD * dot(qq, uAxD);
294	      float rhoQ = length(qq), psQ = atan(dot(qq, uAxR), dot(qq, uAxU));
295	      vec2 uvM = vec2(psQ / 6.2831853 + 0.5, (uMouthRho.x - rhoQ - uMouthRho.z) / (uMouthRho.x - uMouthRho.y));
296	      // explicit gradients without the psi wrap (the seam lies under the water)
297	      vec2 gx = dFdx(uvM), gy = dFdy(uvM);
298	      gx.x = abs(gx.x) > 0.5 ? 0.0 : gx.x; gy.x = abs(gy.x) > 0.5 ? 0.0 : gy.x;
299	      col = textureGrad(uMouthTex, uvM, gx, gy).rgb;
300	      // a soft polished sheen that moves with the view (the painted highlights stay where they were painted)
301	      col += vec3(1.0, 0.86, 0.55) * 0.10 * gl * smoothstep(0.0, 0.2, facing);
302	    }
303	    if (!mouth && uRPaint > 0.0 && part < 2.5) {
304	      // r15 m04rpaint: the user's painted inner ring, straightened (tools/match04/ring_paint04.py), on this ring at its
305	      // own (angle, position inside the period): painted groove on the modeled groove corner, painted bright lip line on
306	      // the modeled lip apex, piecewise linear in between. World-anchored (no projector) -> nothing slides while swimming.
307	      float uu = fract(al / uP) * uP;
308	      float uL = uRLip.y, sL = uRLip.x, uG = min(uRLip.w, uP);
309	      bool bandSide = uu < uL;
310	      float sl = bandSide ? sL / uL : (1.0 - sL) / max(uG - uL, 1e-3);   // ds / du
311	      float sp = bandSide ? uu * sl : min(sL + (uu - uL) * sl, 1.0);
312	      if (uu >= uG) sl = 0.0;
313	      float dax = dFdx(ang), day = dFdy(ang);
314	      dax -= 6.2831853 * floor(dax / 6.2831853 + 0.5); day -= 6.2831853 * floor(day / 6.2831853 + 0.5);
315	      float rj = uRJit * (2.0 * h21(vec2(floor(al / uP), 5.3)) - 1.0);
316	      vec2 uvR = vec2((ang + rj) / 6.2831853 + 0.5, sp);
317	      vec2 gS = vec2(dFdx(al), dFdy(al)) * sl;
318	      if (uRVar > 0.5) {
319	        // r17 m04rpvar: atlas of the painted inner rings 0, 1, 2 (pink-violet sheen / plain copper / pink-left + violet
